import math

def is_square(k):
    if k < 1:
        return False
    root = int(math.isqrt(k))
    return root * root == k

def can_be_cool(n):
    """
    Checks if there exists a permutation of (1, ..., n) such that 
    all prefix sums are not perfect squares.
    """

    # The full sum S_n must not be a square. This is a quick check.
    total_sum = n * (n + 1) // 2
    if is_square(total_sum):
        # The nth prefix sum is the total sum, so if it's a square, it's not cool.
        return False

    # Backtracking search function
    def find_permutation(current_sum, used_mask, length):
        if length == n:
            # This should only be reached if the initial check passed (S_n is not a square)
            return True

        # Try every available number x (1 to n)
        for x in range(1, n + 1):
            # Check if x is unused (using bitmask)
            if not (used_mask & (1 << (x - 1))):

                new_sum = current_sum + x

                # Constraint check: new_sum must not be a square
                if not is_square(new_sum):
                    # Recurse
                    new_mask = used_mask | (1 << (x - 1))
                    if find_permutation(new_sum, new_mask, length + 1):
                        return True

        return False

    # Start the search: initial sum 0, no numbers used (mask 0), length 0
    return find_permutation(0, 0, 0)

# Test for n = 1 to 15
cool_integers = []
for n in range(1, 16):
    if can_be_cool(n):
        cool_integers.append(n)

print(f"Cool integers found up to 15: {cool_integers}")
